import json, time, urllib.request, urllib.error
from datetime import datetime, timezone

BASE='http://localhost:8080'
def request(path, method='GET', auth=False):
    global token, token_fetched
    attempts=0
    while True:
        headers={}
        if auth:
            if token is None or time.time()-token_fetched > 20:
                token=[REDACTED_SECRET]'/token','POST',False)['token']; token_fetched=time.time()
            headers['Authorization']='Bearer '+token
        req=urllib.request.Request(BASE+path, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req,timeout=30) as resp:
                return json.loads(resp.read().decode())
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors='replace')
            if e.code==429:
                delay=float(e.headers.get('Retry-After','1'))
                time.sleep(delay); continue
            if e.code==401 and auth:
                token=None; continue
            attempts+=1
            if attempts>=10: raise RuntimeError(f'{path} failed {e.code}: {body}')
            time.sleep(min(attempts,5))
        except Exception:
            attempts+=1
            if attempts>=10: raise
            time.sleep(min(attempts,5))

token=None; token_fetched=0
# Fetch pages using server's next pointer.
path='/orders?page=1'
seen={}; duplicates=0; total_pages=None; listed=0
while path:
    page=request(path,auth=True)
    total_pages=page.get('total_pages',total_pages)
    for o in page['items']:
        listed+=1
        oid=o['id']
        if oid in seen: duplicates+=1
        else: seen[oid]=o
    path=page.get('next')
    if path and not path.startswith('/'): raise RuntimeError('Unexpected next path '+repr(path))

start=datetime(2025,3,1,tzinfo=timezone.utc)
end=datetime(2025,6,1,tzinfo=timezone.utc)
qual=[]
for o in seen.values():
    dt=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
    if o['status']=='shipped' and start<=dt<end: qual.append(o)

customers={}
for o in qual:
    cid=o['customer_id']
    if cid not in customers: customers[cid]=request('/customers/'+str(cid),auth=True)

by={r:0 for r in ['north','south','east','west']}
for o in qual:
    c=customers[o['customer_id']]
    # half-up nearest cent for integer cents * (100-discount)/100
    num=o['amount_cents']*(100-c['discount_pct'])
    discounted=(num+50)//100
    by[c['region']]+=discounted
result={'total_cents':sum(by.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':by}
print(json.dumps({'pages':total_pages,'listed':listed,'distinct':len(seen),'qualified':len(qual),'customers':len(customers),'result':result},indent=2))
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
